}
scwin.getToday = function() {
    var date = new Date();
    dd = date.getDate() > 9 ? date.getDate() : '0' + date.getDate();
    mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    yy = date.getFullYear();
    var today = yy + '-' + mm + '-' + dd;
    return today;
}
scwin.checkVal = function() {
    return (document.getElementById('inputCalendar2_input') || document.getElementById('mf_inputCalendar2_input')).value == scwin.getToday();
}

